import React, { useCallback, useMemo, useState } from 'react' // Import useState

// packages
import { Skeleton, Tooltip } from 'antd';
import { CaretDownFilled, CaretUpFilled } from '@ant-design/icons';
import { UFCSelect } from 'uxcam-frontend-components';

// utils
import { compactNotation, convertGetTime } from 'Utils/helpers/commonUtils';
import { formatNumberWithCommas } from 'Utils/helpers/numberFormatter';

// styles
import { StatsWrapper, PercentCapsule } from './styles';

// types
import { TStatCard } from './types';

const StatCard: React.FC<TStatCard> = (props) => {
  const { title, value, percent, dataType, selected, onClick, loading, id, tooltip, screenTimeType, setScreenTimeType } = props;
  const containerRef = React.useRef(null);
  const [isSelectOpen, setIsSelectOpen] = useState(false); // Add state for select dropdown visibility
  const invertedPercent = ['session_count', 'crash_free_sessions', 'uifreeze_free_sessions', 'exception_free_sessions', 'screen_count', 'screen_time'];
  const showPercent = useMemo(() => dataType === 'percent', [dataType]);
  const showTime = useMemo(() => dataType === 'time', [dataType]);
  const handleSuccessError = (val: string) => {
    if (val === 'Infinity' || val === 'NaN' || parseFloat(val) === 0) {
      return true;
    }
    return !val?.toString().includes('-');
  };

  const isPositive = invertedPercent.includes(id) ? handleSuccessError(percent) : !handleSuccessError(percent);

  const handlePercentageValue = useCallback((percentValue: number | string) => {
    const modifiedPercent =
      percentValue && percentValue !== 'NaN' && percentValue !== 'Infinity'
        ? `${compactNotation(percentValue, 2)}%` : '';
    return modifiedPercent;
  }, []);

  const tooltipContent = useMemo(() => (
    <>
      {
        showTime ? (
          <b>{convertGetTime({ durationInSecs: value, roundFalse: true })}</b>
        ) : (
          <b>{showPercent ? compactNotation(value, 2) : formatNumberWithCommas(value)}{showPercent && '%'}</b>
        )
      }{' '}
      {tooltip}
    </>
  ), [showPercent, showTime, tooltip, value])

  const showTimeTypeDropdown = useMemo(() => title === 'time on screen' && dataType === 'time', [dataType, title]);
  const isNotAvailable = useMemo(() => percent === 'Infinity' || percent === 'NaN', [percent]);

  // Handler for select dropdown visibility change
  const handleDropdownVisibleChange = (visible: boolean) => {
    setIsSelectOpen(visible);
  };

  return (
    <StatsWrapper active={selected} onClick={onClick}>
      <Skeleton loading={loading} active title paragraph={{ rows: 1 }}>
        <Tooltip title={isSelectOpen ? undefined : tooltipContent} placement="bottomLeft" align={{ offset: [0, -10] }}>
          <span className='container'>
            <span className="title" ref={containerRef}>
              {showTimeTypeDropdown && (
                <UFCSelect
                  className='stat-time-select'
                  defaultValue='averageTime'
                  value={screenTimeType}
                  onChange={setScreenTimeType}
                  getPopupContainer={() => containerRef.current || document.body}
                  onDropdownVisibleChange={handleDropdownVisibleChange} // Add handler
                  renderOptions={[
                    { label: 'Average', value: 'averageTime' },
                    { label: 'Median', value: 'medianTime' }
                  ]}
                />
              )
              }
              {title}
            </span>

            {
              showTime ? (
                <span className='value'>{convertGetTime({ durationInSecs: value, roundFalse: false })}</span>
              ) : (
                <span className="value">{compactNotation(value, 2)}{showPercent && '%'}</span>
              )
            }
          </span>
        </Tooltip>
        <PercentCapsule positive={isPositive} isNotAvailable={isNotAvailable}>
          {isNotAvailable ? (
            <Tooltip title="Previous value was 0, unable to calculate the percentage change." placement='bottom'>
              <span className='percent-na'>N/A</span>
            </Tooltip>
          ) : (
            <>
              {handleSuccessError(percent) ? <CaretUpFilled /> : <CaretDownFilled />}
              <span className="percent">{handlePercentageValue(percent)}</span>
            </>
          )}
        </PercentCapsule>
      </Skeleton>
    </StatsWrapper>
  );
};

export default StatCard;