import styled, { css } from "styled-components";
import { theme } from "theme";

type TPercentCapsule = {
    positive?: boolean;
    isNotAvailable?: boolean;
}

type TStatWrapper = {
    active?: boolean;
}

const StatsWrapper = styled.button<TStatWrapper>`
    width: 100%;
    height: 25%;
    padding: 12px;
    border-radius: 8px;
    border: 1px solid #F3F4F5;
    display: flex;
    align-items: flex-start;
    flex-direction: column;
    cursor: pointer;
    gap: 8px;

    border-color: ${props => props.active ? '#5D97FF' : '#F3F4F5'};
    border-width: ${props => props.active ? '2px' : '1px'};
    background: ${props => props.active ? '#F7FAFF' : '#fff'};

    &:hover {
        background: #F7FAFF;        
    }

    .container {
        display: flex;
        flex-direction: column;
        gap: 8px;
        align-items: flex-start;
    }

    .title {
        font-weight: 500;
        line-height: 14px;
        font-size: 12px;
        color: #737886;
        display: flex;
        align-items: center;
        gap: 2px;
        .ufc-select{
            height: 18px;
            min-width: initial;
            padding: 2px;
            border-color: transparent;
            border-radius: 2px;
            background-color: ${ theme.colors.primary10.toString() };
        &:focus{
            outline: none;
        }
        }
        .ufc-select-dropdown{
            max-width: 120px !important;
        }

        .ufc-select-suffix{
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: white;
            svg {
                height: 10px;
                width: 10px;
                path{
                stroke: ${theme.colors.primarySky.toString()};;
            }
            }
        }
        .ufc-select-item{
            max-width: 97px;
            text-align: left;
            &:hover{
                font-weight: 400;
                color: ${theme.colors.primaryMidnight.toString()};
            }
        }
        .ufc-select-item-option-selected{
            &:hover{
                font-weight: 600;
            }
        }

        .ufc-select-content-value{
            font-size: 12px;
            color: ${theme.colors.primarySky.toString()};
            font-weight: 700;
            line-height: 22px;
    }}

    .value {
        font-size: 22px;
        font-weight: 700;
        line-height: 22px;
    }

    .count {
        font-weight: 700;
        font-size: 18px;
        line-height: 22px;
    }
`

const PercentCapsule = styled.span<TPercentCapsule>`
    display: flex;
    gap: 2px;
    justify-content: center;
    align-items: center;
    border-radius: 12px;
    padding: 4px 8px 4px 6px;
    font-size: 10px;
    line-height: 0px;
    background: ${props => {
        if (props.isNotAvailable) return theme.colors.surface10.toString();
        if (props.positive) return '#EAF9F3';
        return '#FEEEED';
    }};
    color: ${props => {
        if (props.isNotAvailable) return theme.colors.primaryMidnight.toString();;
        if (props.positive) return '#00B87C';
        return '#F4584C';
    }};
    .percent-na{
        height: 10px;
        position: relative;
        top: 5px;
    }
`

export {
    StatsWrapper,
    PercentCapsule,
}