/* eslint-disable no-lone-blocks */
import React, { memo, useMemo } from 'react';

// packages
import { Tabs } from 'antd';
import Highcharts from 'highcharts';
import HighchartsReact from 'highcharts-react-official';

// components
import ReactLoader from 'components/common/reactLoading';
import LoaderAdvanced from 'components/common/LoaderAdvanced';

// hooks
import { useIsAppType } from 'hooks/useIsAppType';
import { formatDisplayTime } from 'Utils/constants';

// styles
import { isEmpty } from 'lodash';
import { GraphWrapper, TabWrapper, TabsContainer } from './styles';

// types
import { GraphDataProps } from '../../types';

// vars
import { analyticsMenu as issueAnalyticsMenu, IssueGraphHeight, webAnalyticsMenu, webStatMenuKeys } from '../../variables';
import EmptyGraph from './EmptyGraph';


const GraphsContainer: React.FC<GraphDataProps> = (props) => {
  const {
    title: titleRaw,
    graphData,
    loading,
    selectedGraphType,
    handleChangeGraphType,
    screenTimeType,
    selectedStat,
  } = props;

  const isWebScreen = useIsAppType('web');

  const data = useMemo(
    () => graphData?.data?.data?.plot,
    [graphData?.data?.data?.plot]
  );

  const modifiedOptions = useMemo(() => {
    if (!data) return {};
  
    const maxLength = 32; // Change this to control truncation length
  
    const truncatedOptions = {
      ...data,
      tooltip: {
        ...data.tooltip,
        backgroundColor: 'rgba(255, 255, 255, 1)',
        useHTML: true,
        style: {
          wordWrap: 'break-word',
          backgroundColor: 'rgba(255, 255, 255, 1)',
        }
      },
      xAxis: {
        ...data.xAxis,
        labels: {
          ...data.xAxis?.labels,
          useHTML: true, 
          outside: true,
          style: {
            opacity: 1,
          },
          formatter () {
            const { value } = this;
            const label = value?.toString() || '';
            const isTruncated = label.length > maxLength;
            const displayed = isTruncated ? `${label.slice(0, maxLength)}...` : label;

            if ( data.xAxis.type === 'datetime' ){
              return formatDisplayTime(value, "MMM D")
            }

            return `<span title="${label}">${displayed}</span>`;
          }
        }
      }
    } as Highcharts.Options;
  
    return truncatedOptions;
  }, [data]);
  

  const title = useMemo(() => {
    const showTimeType = titleRaw === 'Screen time' && isWebScreen;

    if (showTimeType) {
      return screenTimeType === 'averageTime' ? 'Average time on screen' : 'Median time on screen';
    }

    return titleRaw;
  }, [screenTimeType, titleRaw, isWebScreen])

  const analyticsMenu = useMemo(() => {
    if (!isWebScreen) return issueAnalyticsMenu;

    const menuMap = new Map(webAnalyticsMenu.map(item => [item.key, item]));

    const filteredMenuKeys = webStatMenuKeys[selectedStat as keyof typeof webStatMenuKeys] || [];
    return filteredMenuKeys.map(key => menuMap.get(key)).filter(Boolean) as typeof webAnalyticsMenu;
  }, [isWebScreen, selectedStat]);

  return (
    <GraphWrapper>
      <h1 className="title">
        {title}
      </h1>
      <TabsContainer>
        <TabWrapper
          onChange={handleChangeGraphType}
          activeKey={selectedGraphType}
        >
          {analyticsMenu.map(({ name, key }) => (
            <Tabs.TabPane tab={name} key={key}>
              <LoaderAdvanced
                show={loading}
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                message={<ReactLoader type="spin" />}
                backgroundStyle={{
                  backgroundColor: 'rgba(255,255,255,1)',
                }}
              >
                <div style={{ width: '100%', minHeight: IssueGraphHeight }}>
                  {!loading && isEmpty(data) && <EmptyGraph isScreenAnalytics={ isWebScreen }/>}
                  {data && data.series instanceof Array && (
                    <HighchartsReact
                      containerProps={{ style: { height: IssueGraphHeight } }}
                      highcharts={Highcharts}
                      constructorType="chart"
                      options={modifiedOptions}
                    />
                  )}
                </div>
              </LoaderAdvanced>
            </Tabs.TabPane>
          ))}
        </TabWrapper>
      </TabsContainer>
    </GraphWrapper>
  );
};

export default memo(GraphsContainer);
