import React, { useMemo } from 'react';

// packages
import { RootStateOrAny, useSelector } from 'react-redux';

// hooks
import { useIsAppType } from 'hooks/useIsAppType';

// styles
import { StatsWrapper } from './styles';

// components
import StatCard from '../StatCard';

// types
import { TStatContainer, TIssueBoxData } from './types';
import { IssueType } from '../../types';
import { DataType } from '../StatCard/types';

const getStatCrashTitleAndAttr = (issueType: string) => {
  switch (issueType) {
    case IssueType.crashes:
      return {
        title: 'Crashes',
        attr: 'crash_count',
      };
    case IssueType.freezes:
      return {
        title: 'UI freezes',
        attr: 'uifreeze_count',
      };
    case IssueType.exceptions:
      return {
        title: 'Exceptions',
        attr: 'exception_count',
      };
    default:
      return {
        title: 'Crashes',
        attr: 'crash_count',
      };
  }
}

const getStatCrashFreeTitleAndAttr = (issueType: string) => {
  switch (issueType) {
    case IssueType.crashes:
      return {
        title: 'Crash free sessions',
        attr: 'crash_free_sessions',
      };
    case IssueType.freezes:
      return {
        title: 'UI freeze free sessions',
        attr: 'uifreeze_free_sessions',
      };
    case IssueType.exceptions:
      return {
        title: 'Sessions without exceptions',
        attr: 'exception_free_sessions',
      };
    default:
      return {
        title: 'Crash free sessions',
        attr: 'crash_free_sessions',
      };
  }
}

const getStatAffectedUserTitleAndAttr = (issueType: string) => {
  switch (issueType) {
    case IssueType.crashes:
      return {
        attr: 'crash_unique_user_count',
      };
    case IssueType.freezes:
      return {
        attr: 'uifreeze_unique_user_count',
      };
    case IssueType.exceptions:
      return {
        attr: 'exception_unique_user_count',
      };
    default:
      return {
        attr: 'crash_unique_user_count',
      };
  }
}

const StatsContainer: React.FC<TStatContainer> = (props) => {
  const { selectedStat, setSelectedStat, reason, boxData, isLoading, dateString, screenTimeType = undefined, setScreenTimeType = undefined } = props;
  const {
    urlReducer: { issueType },
  } = useSelector((state: RootStateOrAny) => state);
  const isWebApp = useIsAppType('web');

  const tooltipTitleIssueType = useMemo(() => issueType === IssueType.freezes ? getStatCrashTitleAndAttr(issueType).title : getStatCrashTitleAndAttr(issueType).title.toLocaleLowerCase(), [issueType])

  const MobileStatList = useMemo(() => ([
    {
      id: getStatCrashFreeTitleAndAttr(issueType).attr,
      title: getStatCrashFreeTitleAndAttr(issueType).title,
      ...boxData?.issue_free_session as TIssueBoxData,
      dataType: 'percent',
      tooltip: `sessions recorded without ${tooltipTitleIssueType} ${reason ? `due to ${reason}` : ''} during ${dateString}`
    },
    {
      id: getStatCrashTitleAndAttr(issueType).attr,
      title: getStatCrashTitleAndAttr(issueType).title,
      ...boxData?.total_issue as TIssueBoxData,
      dataType: 'count',
      tooltip: `${boxData?.total_issue?.value > 1 ? 'sessions' : 'session'} recorded with ${tooltipTitleIssueType} ${reason ? `due to ${reason}` : ''} during ${dateString}`,
    },
    {
      id: getStatAffectedUserTitleAndAttr(issueType).attr,
      title: 'Affected users',
      ...boxData?.user_with_issue as TIssueBoxData,
      dataType: 'count',
      tooltip: `${boxData?.user_with_issue?.value > 1 ? 'users' : 'user'} affected with ${tooltipTitleIssueType} ${reason ? `due to ${reason}` : ''} during ${dateString}`,
    },
    {
      id: 'session_count',
      title: 'Total sessions',
      ...boxData?.total_session as TIssueBoxData,
      dataType: 'count',
      tooltip: `total sessions recorded during ${dateString}`
    },
  ]), [boxData, issueType, reason, dateString, tooltipTitleIssueType])

  const WebStatList = useMemo(() => ([
    {
      id: 'screen_count',
      title: 'Screen visits',
      ...boxData?.screen_count as TIssueBoxData,
      dataType: 'count',
      tooltip: `screen visits during ${dateString}`
    },
    {
      id: 'bounce_rate',
      title: 'Bounce rate',
      ...boxData?.bounce_rate as TIssueBoxData,
      dataType: 'percent',
      tooltip: `screen bounce rate during ${dateString}`
    },
    {
      id: 'screen_time',
      title: 'time on screen',
      ...boxData?.screen_time as TIssueBoxData,
      dataType: 'time',
      tooltip: `${screenTimeType === 'averageTime' ? 'average' : 'median'} time spent on screen during ${dateString}`
    },
    {
      id: 'screen_with_issue',
      title: 'Screen with issues',
      ...boxData?.screen_with_issue as TIssueBoxData,
      dataType: 'count',
      tooltip: `screen visits with Rage or Dead clicks during ${dateString}`
    }
  ]), [boxData?.bounce_rate, boxData?.screen_count, boxData?.screen_time, boxData?.screen_with_issue, dateString, screenTimeType])

  const StatList = useMemo(() => {
    if (isWebApp) return WebStatList;
    return MobileStatList;
  }
    , [isWebApp, MobileStatList, WebStatList]);


  return (
    <StatsWrapper>
      {StatList.map((item) => (
        <StatCard
          id={item.id}
          key={`issue-stat-box-${item.title}`}
          title={item.title}
          value={item.value}
          percent={item.percent}
          dataType={item.dataType as DataType}
          onClick={() => setSelectedStat(item.id)}
          selected={selectedStat === item.id}
          loading={isLoading}
          tooltip={item.tooltip}
          screenTimeType={screenTimeType}
          setScreenTimeType={setScreenTimeType}
        />
      ))}
    </StatsWrapper>
  );
};

export default StatsContainer;
